using System.Collections;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
public sealed class GridShiftMainMenu:MonoBehaviour {
 public Texture2D cityBackground;
 CanvasGroup menu,splash,loading;RectTransform background;GameObject credits;TMP_Text loadingText;GridShiftUILoading loadingView;bool busy;
 void Start(){Time.timeScale=1;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;Build();StartCoroutine(Intro());}
 RectTransform Rect(string name,Transform parent,Vector2 size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=size;return r;}
 TMP_Text Text(Transform parent,string value,int font,Vector2 size,Vector2 at){var r=Rect("Text",parent,size);r.anchoredPosition=at;var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.text=value;t.fontSize=font;t.color=Color.white;t.raycastTarget=false;return t;}
 Button Button(Transform parent,string label,Vector2 at,UnityEngine.Events.UnityAction action){var r=Rect(label,parent,new Vector2(465,62));r.anchoredPosition=at;r.gameObject.AddComponent<Image>().color=Color.white;var b=r.gameObject.AddComponent<Button>();var c=b.colors;c.normalColor=new Color(.065f,.09f,.13f,.96f);c.highlightedColor=new Color(.23f,.20f,.08f);c.selectedColor=new Color(.14f,.15f,.13f);c.pressedColor=new Color(.42f,.34f,.07f);c.disabledColor=new Color(.055f,.065f,.08f,.45f);b.colors=c;b.onClick.AddListener(action);var t=Text(r,label,23,new Vector2(360,45),new Vector2(25,-2));t.alignment=TextAlignmentOptions.MidlineLeft;var line=Rect("Accent",r,new Vector2(3,34));line.anchoredPosition=new Vector2(-229,0);line.gameObject.AddComponent<Image>().color=new Color(.95f,.8f,.2f);GridShiftUITheme.Button(b,label=="Novo Jogo"||label=="Continuar");return b;}
 CanvasGroup Overlay(string name,Color color){var r=Rect(name,transform,Vector2.zero);r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;r.gameObject.AddComponent<Image>().color=color;return r.gameObject.AddComponent<CanvasGroup>();}
 void Build(){var canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=100;var scaler=gameObject.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;gameObject.AddComponent<GraphicRaycaster>();
  background=Rect("CityBackground",transform,new Vector2(1920,1080));background.anchorMin=Vector2.zero;background.anchorMax=Vector2.one;background.offsetMin=background.offsetMax=Vector2.zero;var raw=background.gameObject.AddComponent<RawImage>();raw.texture=GridShiftUITheme.Get("Fundo_Menu_Principal_1920x1080")?.texture??cityBackground;raw.color=raw.texture!=null?Color.white:new Color(.025f,.04f,.065f);raw.raycastTarget=false;
  menu=Overlay("Menu",new Color(.012f,.023f,.04f,.30f));var content=Rect("Content",menu.transform,new Vector2(620,850));content.anchorMin=content.anchorMax=new Vector2(.24f,.5f);var brand=GridShiftBranding.Current;
  if(brand!=null&&brand.gs!=null){var r=Rect("OriginalGS",content,new Vector2(96,60));r.anchoredPosition=new Vector2(-180,345);var image=r.gameObject.AddComponent<Image>();image.sprite=GridShiftUITheme.Get("GS_Simbolo_Transparente")??brand.gs;image.preserveAspect=true;image.raycastTarget=false;}
  Text(content,"SIMULAÇÃO  /  LOGÍSTICA URBANA",15,new Vector2(465,28),new Vector2(0,280)).color=new Color(.95f,.8f,.2f);GridShiftUITheme.Art(content,"GRIDSHIFT_Logo_Horizontal",new Vector2(500,140),new Vector2(0,216));Text(content,"Gerencie sua empresa.\nConecte a cidade.",25,new Vector2(465,90),new Vector2(0,127)).color=new Color(.73f,.8f,.89f);
  Button(content,"Novo Jogo",new Vector2(0,-58),()=>StartGame(false));var resume=Button(content,"Continuar",new Vector2(0,20),()=>StartGame(true));resume.interactable=DeliverySaveStore.Read(out _);Button(content,"Configurações",new Vector2(0,-136),()=>{menu.interactable=false;PauseMenu.Instance.OpenSettingsFromMainMenu(()=>menu.interactable=true);});Button(content,"Controles",new Vector2(0,-214),()=>GridShiftOperationsUI.Instance?.Open("controls",true));Button(content,"Créditos",new Vector2(0,-292),()=>credits.SetActive(true));Button(content,"Sair",new Vector2(0,-370),Quit);
  Text(menu.transform,"GRIDSHIFT  ·  VERSÃO 9.0\nEntregas locais demonstráveis · Urban Flow sem sincronização de backend",16,new Vector2(750,58),new Vector2(440,-470)).color=new Color(.65f,.73f,.83f);
  credits=Rect("Credits",menu.transform,new Vector2(850,620)).gameObject;credits.AddComponent<Image>().color=new Color(.025f,.04f,.065f,.99f);Text(credits.transform,"CRÉDITOS",36,new Vector2(720,60),new Vector2(0,220));Text(credits.transform,"PROJETO INTEGRADOR SENAI\n\nAnna Clara Lara Pereira — Multimídia\nGeovanna Lopes Fagundes Dalla — Design Gráfico\nGustavo Henriques Barros — Programação de Jogos Digitais\nThéo Henrique Barros dos Santos — Design Gráfico\nPedro do Nascimento Braga — Análise e Desenvolvimento de Sistemas\n\nUnity 6 · C# · URP · TextMesh Pro\nInput System · Unity Web Browser / CEF",21,new Vector2(760,390),new Vector2(0,-5));Button(credits.transform,"Voltar",new Vector2(0,-240),()=>credits.SetActive(false));GridShiftUITheme.Surface(credits.GetComponent<Image>(),"Painel_Menu_Cantos_Amarelos");credits.SetActive(false);
  splash=Overlay("BrandIntro",new Color(.005f,.008f,.012f,1));var logo=Rect("GSOriginal",splash.transform,new Vector2(192,120));var logoImage=logo.gameObject.AddComponent<Image>();logoImage.sprite=GridShiftUITheme.Get("GS_Simbolo_Transparente")??(brand!=null?brand.gs:null);logoImage.preserveAspect=true;logoImage.enabled=logoImage.sprite!=null;Text(splash.transform,"GRIDSHIFT",30,new Vector2(400,60),new Vector2(0,-115)).alignment=TextAlignmentOptions.Center;var accent=Rect("GlowAccent",splash.transform,new Vector2(95,2));accent.anchoredPosition=new Vector2(0,-158);accent.gameObject.AddComponent<Image>().color=new Color(.95f,.8f,.2f);splash.alpha=0;
  loading=Overlay("Loading",new Color(.006f,.012f,.02f,1));loadingText=Text(loading.transform,"GRIDSHIFT\nPreparando a cidade · 0%",35,new Vector2(900,200),Vector2.zero);loadingText.alignment=TextAlignmentOptions.Center;loadingView=loading.gameObject.AddComponent<GridShiftUILoading>();loadingView.Initialize();loading.gameObject.SetActive(false);menu.alpha=0;menu.interactable=menu.blocksRaycasts=false;
 }
 IEnumerator Intro(){for(float t=0;t<2.6f;t+=Time.unscaledDeltaTime){splash.alpha=t<.6f?t/.6f:t>2?1-(t-2)/.6f:1;splash.transform.GetChild(0).localScale=Vector3.one*Mathf.Lerp(.96f,1.025f,t/2.6f);yield return null;}splash.gameObject.SetActive(false);var buttons=menu.GetComponentsInChildren<Button>();foreach(var b in buttons)b.gameObject.AddComponent<CanvasGroup>().alpha=0;for(float t=0;t<.45f;t+=Time.unscaledDeltaTime){menu.alpha=t/.45f;yield return null;}menu.alpha=1;for(float t=0;t<.45f;t+=Time.unscaledDeltaTime){for(int i=0;i<buttons.Length;i++)buttons[i].GetComponent<CanvasGroup>().alpha=Mathf.Clamp01((t-i*.045f)/.16f);yield return null;}foreach(var b in buttons)b.GetComponent<CanvasGroup>().alpha=1;menu.interactable=menu.blocksRaycasts=true;}
 public void StartGame(bool resume){if(busy)return;if(resume){if(!DeliverySaveStore.Read(out var data))return;DeliverySaveStore.Pending=data;}else{DeliverySaveStore.Pending=null;DeliverySaveStore.StartFresh=true;}StartCoroutine(Load());}
 IEnumerator Load(){busy=true;menu.interactable=menu.blocksRaycasts=false;loading.gameObject.SetActive(true);DontDestroyOnLoad(gameObject);var operation=SceneManager.LoadSceneAsync("SampleScene",LoadSceneMode.Single);while(!operation.isDone){loadingView.Progress(operation.progress/.9f);loadingText.text="GRIDSHIFT\nPreparando a cidade · "+Mathf.RoundToInt(operation.progress/.9f*100)+"%";yield return null;}loadingText.text="GRIDSHIFT\nCidade pronta · 100%";yield return null;Destroy(gameObject);}
 void Update(){if(background!=null)background.localScale=Vector3.one*(1.025f+.004f*Mathf.Sin(Time.unscaledTime*.15f));if(credits!=null&&credits.activeSelf&&UnityEngine.InputSystem.Keyboard.current!=null&&UnityEngine.InputSystem.Keyboard.current.escapeKey.wasPressedThisFrame){GridShiftUITheme.Surface(credits.GetComponent<Image>(),"Painel_Menu_Cantos_Amarelos");credits.SetActive(false);EscapeInput.Consume();}}
 void Quit(){
#if UNITY_EDITOR
 UnityEditor.EditorApplication.isPlaying=false;
#else
 Application.Quit();
#endif
 }
}





